package com.bookstore.application.sequences;
import java.util.*; import java.util.function.ToIntFunction;
public final class SequenceOrdering { private SequenceOrdering(){} public static <T> List<SequencedItem<T>> assignLineSequence(Iterable<T> lines){Objects.requireNonNull(lines); List<SequencedItem<T>> out=new ArrayList<>(); int i=1; for(T x:lines)out.add(new SequencedItem<>(i++,x)); return List.copyOf(out);} public static <T> List<T> orderByPriority(Collection<T> items,ToIntFunction<T> selector){Objects.requireNonNull(items); Set<Integer> seen=new HashSet<>(); for(T x:items)if(!seen.add(selector.applyAsInt(x)))throw new IllegalStateException("Priority is duplicated; sequence priority ties must be explicit before ordering."); return items.stream().sorted(Comparator.comparingInt(selector)).toList();} public record SequencedItem<T>(int sequence,T value){} }
